	port: number,
	extId: string,
	page: string,
): Promise<{ webSocketDebuggerUrl?: string } | null> {
	const targets = (await cdpFetch(port, "/json/list")) as Array<{
		type: string;
		url?: string;
		webSocketDebuggerUrl?: string;
	}>;
	const targetUrl = stripUrlSuffix(`chrome-extension://${extId}/${page}`);

