		const text = String(data);
		const portLine = text.match(
			/Started dev server @ http:\/\/localhost:(\d+)/,
		);
		if (portLine) {
			const actualPort = portLine[1];
			if (actualPort !== String(wxtPort)) {
				console.log(`\u2139 WXT using port ${actualPort}`);
			}
