# WXT Global Scripts

Global helper scripts for WXT extension projects. `wxtu` is the main entrypoint.
These scripts are used in common by `/home/easydev/dev/extensions/ebook-scroller`,
`/home/easydev/dev/extensions/scroll-detox`, and
`/home/easydev/dev/extensions/dev-selector`.

Browser lifecycle (launch, stop, minimize) is managed by the global
`browser` command. The wrapper scripts in this directory delegate to it.

## Command Roles

- `wxtu dev chrome`: start the Chrome WXT dev server.
- `wxtu dev chrome` forwards unknown flags to `browser open`; use `--` to pass through overlapping flags such as `--port`.
- The dev window loads only the extension under development. A blocker installed by a managed policy holds page loads until its own lists settle, so it — and every other profile extension — stays out unless `WXT_CHROME_KEEP_EXTENSIONS=1` (or `--keep-extensions`) asks for it. `--dev-selector` adds the Dev Selector extension (a section-picking dev tool) next to it; it is forwarded to `browser open`, so it applies only when the run launches a new browser.
- A run reuses the browser already on the CDP port. `--normal` is a person asking to look at the build, so it leaves that browser alone and opens a separate visible window on the next free port with a `<profile>-view` profile; the dev server's lifecycle stays tied to the original browser.
- Parallel dev sessions each start their own WXT server (3000, 3001, …) but write the same `.output/<browser>-mv3-dev`. The background bakes in the ws port of whichever server built last; once that server stops, every browser on that output misses the content-script handshake on its next extension reload or launch.
- `wxtu dev firefox`: start the Firefox WXT dev server.
- `wxtu build`: build Chrome and Firefox bundles in parallel.
- `wxtu zip`: create Chrome and Firefox zip artifacts in parallel.
- `wxtu version`: bump version and package release artifacts.
- `wxtu submit`: submit extension packages to browser stores.
- `wxtu minimize cdp`: minimize a Chromium window via CDP.
- `wxtu minimize kwin`: minimize the active window via KWin.
- `wxtu listing firefox`: fill Firefox Add-on (AMO) listing fields via CDP automation.
- `wxtu listing chrome`: fill Chrome Web Store listing fields.
- `wxtu android emulator`: start an Android emulator with stable defaults.
- `wxtu android firefox install`: build and reinstall the extension on Firefox Android.
- `wxtu android firefox manager`: open Firefox Android's add-ons/settings surface.
- `wxtu android firefox page`: same helper as `manager`, with optional target arguments.

## Internal Files

- `wxtu.mjs`: command router.
- `dev-wxt-utils.mjs`: shared WXT API loader and dev-server arg parser.
- `dev-chrome-wxt.mjs`: Chrome helper that runs WXT in manual-runner mode.
- `dev-firefox-wxt.mjs`: Firefox helper that runs WXT with inline `startUrls` overrides.
- `android-emu.mjs`: Android emulator launcher.
- `android-firefox.mjs`: Firefox Android install and page helpers.
- `run-wxt-targets.mjs`: shared parallel build/zip runner.

#!/usr/bin/env node
import { execFileSync, spawn } from "node:child_process";
import http from "node:http";
import path from "node:path";
import { existsSync, mkdirSync, openSync, readFileSync } from "node:fs";
import net from "node:net";
import { fileURLToPath } from "node:url";
import { startSampleServer, SAMPLE_REGISTRY } from "./sample-dev.mjs";
import { consumeCommonDevArg } from "./dev-wxt-utils.mjs";
import { WXTU_CONFIG } from "./config.mjs";

function readBooleanEnv(name, fallback) {
	const value = process.env[name];
	return value == null ? fallback : /^(1|true|yes)$/i.test(value);
}

function getDefaultChromiumDataDir() {
	const packageJsonPath = path.join(process.cwd(), "package.json");
	let packageName = path.basename(process.cwd());

	if (existsSync(packageJsonPath)) {
		try {
			const pkg = JSON.parse(readFileSync(packageJsonPath, "utf8"));
			if (typeof pkg.name === "string" && pkg.name.trim()) {
				packageName = pkg.name.trim();
			}
		} catch {
			// Fall back to the current directory name when package.json can't be read.
		}
	}

	const safeName = packageName.replace(/[^a-zA-Z0-9._-]+/g, "-");
	return path.resolve(".user-data", `chrome-${safeName}`);
}

const CHROMIUM_DATA_DIR = path.resolve(
	process.env.WXT_CHROME_DATA_DIR ?? getDefaultChromiumDataDir(),
);
const CHROME_CONFIG = WXTU_CONFIG.chrome;
const CHROME_DEBUG_PORT = parseInt(
	process.env.WXT_CHROME_DEBUG_PORT ?? String(CHROME_CONFIG.defaultCdpPort),
	10,
);
const CHROME_BIN = process.env.WXT_CHROME_BIN || CHROME_CONFIG.browserBinary;
const START_MINIMIZED = readBooleanEnv(
	"WXT_CHROME_MINIMIZE",
	CHROME_CONFIG.startMinimized,
);
const DEV_LOCALE =
	process.env.WXT_CHROME_LOCALE?.trim() ||
	process.env.BROWSER_LOCALE?.trim() ||
	CHROME_CONFIG.defaultLocale;
// The dev window runs with only the extension under development. A blocker
// installed by a managed policy (uBlock, say) holds page loads until its own
// filter lists settle, so it stays out unless asked for.
const KEEP_EXTENSIONS = readBooleanEnv("WXT_CHROME_KEEP_EXTENSIONS", false);
const DEFAULT_WXT_PORT = CHROME_CONFIG.defaultWxtPort;
const DETACHED_CHILD_ENV = "WXTU_DEV_CHROME_DETACHED_CHILD";
const DEFAULT_START_URL = CHROME_CONFIG.defaultStartUrl;
const DEV_CHROME_LOG = path.resolve(
	process.env.WXT_DEV_CHROME_LOG ?? CHROME_CONFIG.devLogPath,
);
const SCRIPT_PATH = fileURLToPath(import.meta.url);
const SCRIPT_DIR = path.dirname(SCRIPT_PATH);
const WXT_CHROME_SERVER_SCRIPT = path.join(SCRIPT_DIR, "dev-chrome-wxt.mjs");
const isDetachedChild = process.env[DETACHED_CHILD_ENV] === "1";
const BROWSER_OPEN_VALUE_FLAGS = new Set([
	"--binary",
	"--browser-arg",
	"--load-extension",
	"--locale",
	"--port",
	"--url",
	"--user-data",
]);
const BROWSER_OPEN_BOOLEAN_FLAGS = new Set([
	"--clean",
	"--dev-selector",
	"--dry-run",
	"--headless",
	"--help",
	"--json",
	"--keep-extensions",
	"--minimize",
	"--status",
]);

const args = process.argv.slice(2);
let startUrl = process.env.WXT_START_URL || process.env.URL || "";
const scriptArgs = [];
const serverArgs = [];
const browserArgs = [];
let detachedMode = true;
let sampleName = null;
let sawWxtRoot = false;
let explicitWxtPort = null;

function consumeControlChromeArg(args, index) {
	const arg = args[index];
	if (BROWSER_OPEN_VALUE_FLAGS.has(arg)) return index + 1;
	if (BROWSER_OPEN_BOOLEAN_FLAGS.has(arg)) return index;
	return null;
}

function resolveChromeSessionOptions() {
	const options = {
		port: CHROME_DEBUG_PORT,
		url: startUrl || DEFAULT_START_URL,
		userDataDir: CHROMIUM_DATA_DIR,
		locale: DEV_LOCALE,
	};

	for (let i = 0; i < browserArgs.length; i++) {
		const arg = browserArgs[i];
		switch (arg) {
			case "--port":
				options.port = parseInt(browserArgs[++i], 10);
				break;
			case "--url":
				options.url = browserArgs[++i] ?? options.url;
				break;
			case "--user-data":
				options.userDataDir = path.resolve(
					browserArgs[++i] ?? options.userDataDir,
				);
				break;
			case "--locale":
				options.locale = browserArgs[++i] ?? options.locale;
				break;
		}
	}

	return options;
}

for (let i = 0; i < args.length; i++) {
	const arg = args[i];
	if (arg === "--") {
		const passthroughArgs = args.slice(i + 1);
		browserArgs.push(...passthroughArgs);
		scriptArgs.push(arg, ...passthroughArgs);
		break;
	}
	if (!startUrl && (arg.startsWith("http://") || arg.startsWith("https://"))) {
		startUrl = arg;
	} else if (arg === "--detached") {
		detachedMode = true;
		scriptArgs.push(arg);
	} else if (arg === "--foreground") {
		detachedMode = false;
		scriptArgs.push(arg);
	} else if (arg === "--sample") {
		sampleName = args[++i];
		if (!sampleName || !SAMPLE_REGISTRY[sampleName]) {
			console.error(
				`--sample requires one of: ${Object.keys(SAMPLE_REGISTRY).join(", ")}`,
			);
			process.exit(1);
		}
		scriptArgs.push(arg, sampleName);
	} else {
		const consumedIndex = consumeCommonDevArg(args, i);
		if (consumedIndex != null) {
			const forwarded = args.slice(i, consumedIndex + 1);
			if ((arg === "--port" || arg === "-p") && forwarded[1]) {
				explicitWxtPort = parseInt(forwarded[1], 10);
			}
			serverArgs.push(...forwarded);
			scriptArgs.push(...forwarded);
			i = consumedIndex;
		} else if (arg.startsWith("-")) {
			const browserConsumedIndex = consumeControlChromeArg(args, i);
			if (browserConsumedIndex != null) {
				const forwarded = args.slice(i, browserConsumedIndex + 1);
				browserArgs.push(...forwarded);
				scriptArgs.push(...forwarded);
				i = browserConsumedIndex;
			} else {
				browserArgs.push(arg);
				scriptArgs.push(arg);
			}
		} else if (!sawWxtRoot) {
			sawWxtRoot = true;
			serverArgs.push(arg);
			scriptArgs.push(arg);
		} else {
			browserArgs.push(arg);
			scriptArgs.push(arg);
		}
	}
}

function isPortAvailableOnHost(port, host) {
	return new Promise((resolve) => {
		const server = net.createServer();
		server.unref();
		server.on("error", (error) => {
			if (error?.code === "EAFNOSUPPORT") {
				resolve(true);
				return;
			}
			resolve(false);
		});
		server.listen({ port, host }, () => {
			server.close(() => resolve(true));
		});
	});
}

async function isPortAvailable(port) {
	const [ipv4Available, ipv6Available] = await Promise.all([
		isPortAvailableOnHost(port, "127.0.0.1"),
		isPortAvailableOnHost(port, "::1"),
	]);
	return ipv4Available && ipv6Available;
}

async function findAvailablePort(start = DEFAULT_WXT_PORT) {
	for (let p = start; p < start + 100; p++) {
		if (await isPortAvailable(p)) return p;
	}
	throw new Error(`No available port found starting from ${start}`);
}

function resolveOutDir() {
	return path.join(process.cwd(), ".output", "chrome-mv3-dev");
}

let wxt;

function startDetachedChild() {
	mkdirSync(path.dirname(DEV_CHROME_LOG), { recursive: true });
	const logFd = openSync(DEV_CHROME_LOG, "a");
	const child = spawn(process.execPath, [SCRIPT_PATH, ...scriptArgs], {
		cwd: process.cwd(),
		detached: true,
		stdio: ["ignore", logFd, logFd],
		env: {
			...process.env,
			WXT_START_URL: startUrl,
			[DETACHED_CHILD_ENV]: "1",
		},
	});

	child.on("error", (error) => {
		console.error(`Failed to start detached dev session: ${error.message}`);
		process.exit(1);
	});

	child.unref();

	console.log(`Started detached dev session: ${child.pid}`);
	console.log(`Log file: ${DEV_CHROME_LOG}`);
	const sessionOptions = resolveChromeSessionOptions();
	console.log(
		`CDP port: ${sessionOptions.port} (browser close still stops WXT)`,
	);
}

function isChromeDebugEndpointAlive(port) {
	return new Promise((resolve) => {
		const req = http.get(
			{
				host: "127.0.0.1",
				port,
				path: "/json/version",
				timeout: 1500,
			},
			(res) => {
				res.resume();
				resolve(res.statusCode === 200);
			},
		);

		req.on("timeout", () => {
			req.destroy();
			resolve(false);
		});

		req.on("error", () => resolve(false));
	});
}

function watchChromeExit(port) {
	let missedChecks = 0;
	const interval = setInterval(async () => {
		if (await isChromeDebugEndpointAlive(port)) {
			missedChecks = 0;
			return;
		}

		missedChecks += 1;
		if (missedChecks < 3) return;

		clearInterval(interval);
		console.log("\n\u2139 Browser closed \u2014 shutting down dev server");
		wxt.kill();
		process.exit(0);
	}, 2000);
}

async function launchChrome() {
	const outDir = resolveOutDir();
	const sessionOptions = resolveChromeSessionOptions();
	const url = sessionOptions.url;

	// --normal is a person asking to look at the dev build: it gets a window of
	// its own instead of a reused background browser. A second Chromium cannot
	// share a profile dir, so it runs on its own port with a sibling profile.
	const wantsVisibleWindow = browserArgs.includes("--normal");
	let launchPort = sessionOptions.port;
	let separateWindow = false;

	if (await isChromeDebugEndpointAlive(sessionOptions.port)) {
		if (!wantsVisibleWindow) {
			console.log(
				`\nℹ Browser already running on port ${sessionOptions.port}; reusing existing Chromium session`,
			);
			console.log(`  profile: ${sessionOptions.userDataDir}`);
			watchChromeExit(sessionOptions.port);
			return;
		}

		launchPort = await findAvailablePort(sessionOptions.port + 1);
		separateWindow = true;
		console.log(
			`\nℹ Browser on port ${sessionOptions.port} stays; opening a separate visible window on ${launchPort}`,
		);
	}

	const ctrlArgs = [
		"open",
		"--port",
		String(launchPort),
		"--load-extension",
		outDir,
		"--locale",
		sessionOptions.locale,
		"--url",
		url,
		"--json",
	];

	if (START_MINIMIZED) {
		ctrlArgs.push("--minimize");
	}

	if (separateWindow) {
		ctrlArgs.push("--user-data", `${sessionOptions.userDataDir}-view`);
	} else if (process.env.WXT_CHROME_DATA_DIR) {
		ctrlArgs.push("--user-data", CHROMIUM_DATA_DIR);
	}

	if (KEEP_EXTENSIONS) {
		ctrlArgs.push("--keep-extensions");
	}

	ctrlArgs.push(...browserArgs);

	try {
		const result = execFileSync("browser", ctrlArgs, {
			encoding: "utf-8",
			timeout: 30000,
		});
		const output = JSON.parse(result.trim());

		console.log(
			`\n✓ Browser launched (chromium) on port ${output.port} → ${url}`,
		);
		console.log(
			`  profile: ${output.userDataDir ?? sessionOptions.userDataDir}`,
		);
		console.log(`  extension: ${outDir}`);
		console.log(`  locale: ${output.locale ?? sessionOptions.locale}`);
		console.log(`  window state: ${output.windowState}`);

		// A separate window is not the dev session's browser: its own lifecycle
		// stays tied to the background browser the run is developing against.
		watchChromeExit(
			separateWindow
				? sessionOptions.port
				: (output.port ?? launchPort),
		);
	} catch (error) {
		console.error(`Failed to launch browser: ${error.stderr || error.message}`);
		wxt.kill();
		process.exit(1);
	}
}

function waitForWxtReady(child) {
	return new Promise((resolve) => {
		let ready = false;

		const checkReady = (data) => {
			const text = String(data);
			if (
				text.includes("as an unpacked extension manually") ||
				text.includes("Opened browser") ||
				text.includes("Press o + enter")
			) {
				if (!ready) {
					ready = true;
					resolve();
				}
			}
		};

		child.stdout?.on("data", checkReady);
		child.stderr?.on("data", checkReady);

		child.on("error", () => {
			if (!ready) {
				ready = true;
				resolve();
			}
		});

		child.on("close", () => {
			if (!ready) {
				ready = true;
				resolve();
			}
		});
	});
}

async function main() {
	if (detachedMode && !isDetachedChild) {
		startDetachedChild();
		return;
	}

	let sampleChild = null;

	if (sampleName) {
		const { child, url } = await startSampleServer(sampleName);
		sampleChild = child;
		if (!startUrl) startUrl = url;
	}

	const wxtPort =
		explicitWxtPort != null && !Number.isNaN(explicitWxtPort)
			? explicitWxtPort
			: await findAvailablePort(DEFAULT_WXT_PORT);

	const wxtEnv = {
		...process.env,
		WXT_START_URL: startUrl,
		CHOKIDAR_USEPOLLING: process.env.CHOKIDAR_USEPOLLING ?? "1",
	};

	wxt = spawn(
		process.execPath,
		[WXT_CHROME_SERVER_SCRIPT, "--port", String(wxtPort), ...serverArgs],
		{
			cwd: process.cwd(),
			stdio: [detachedMode ? "pipe" : "inherit", "pipe", "pipe"],
			env: wxtEnv,
		},
	);

	wxt.stdout?.on("data", (data) => {
		const text = String(data);
		const portLine = text.match(
			/Started dev server @ http:\/\/localhost:(\d+)/,
		);
		if (portLine) {
			const actualPort = portLine[1];
			if (actualPort !== String(wxtPort)) {
				console.log(`\u2139 WXT using port ${actualPort}`);
			}
		}
		process.stdout.write(data);
	});
	wxt.stderr?.pipe(process.stderr);

	wxt.on("error", (error) => {
		console.error(`Failed to start wxt (chrome): ${error.message}`);
		process.exit(1);
	});

	wxt.on("close", (code, signal) => {
		if (sampleChild && !sampleChild.killed) sampleChild.kill();
		if (signal) process.kill(process.pid, signal);
		else process.exit(code ?? 0);
	});

	await waitForWxtReady(wxt);
	await launchChrome();
}

main();
