function isChromeDebugEndpointAlive(port) {
	return new Promise((resolve) => {
		const req = http.get(
			{
				host: "127.0.0.1",
				port,
				path: "/json/version",
				timeout: 1500,
			},
			(res) => {
				res.resume();
				resolve(res.statusCode === 200);
			},
		);

		req.on("timeout", () => {
			req.destroy();
			resolve(false);
		});

		req.on("error", () => resolve(false));
	});
