function watchChromeExit(port) {
	let missedChecks = 0;
	const interval = setInterval(async () => {
		if (await isChromeDebugEndpointAlive(port)) {
			missedChecks = 0;
			return;
		}

		missedChecks += 1;
		if (missedChecks < 3) return;

